import{_ as a,o as e,c as s,a2 as d}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"⚡ Ant Design + ERP/CRM 速记卡","description":"","frontmatter":{},"headers":[],"relativePath":"面试/5-AntDesign-ERP速记卡.md","filePath":"面试/5-AntDesign-ERP速记卡.md","lastUpdated":1792941182000}'),n={name:"面试/5-AntDesign-ERP速记卡.md"};function o(r,t,c,i,l,p){return e(),s("div",null,[...t[0]||(t[0]=[d(`<h1 id="⚡-ant-design-erp-crm-速记卡" tabindex="-1">⚡ Ant Design + ERP/CRM 速记卡 <a class="header-anchor" href="#⚡-ant-design-erp-crm-速记卡" aria-label="Permalink to &quot;⚡ Ant Design + ERP/CRM 速记卡&quot;">​</a></h1><blockquote><p><strong>极联股份 · 前端 React 工程师（8-9K · 深圳龙岗大运）面试专用</strong> 用法：面试前 10 分钟扫一遍。每题只记<strong>一句话结论</strong>，细节想不起来就顺着下面的链接翻。</p></blockquote><hr><h2 id="🎯-一、30-秒自我介绍-按这家-jd-改" tabindex="-1">🎯 一、30 秒自我介绍（按这家 JD 改） <a class="header-anchor" href="#🎯-一、30-秒自我介绍-按这家-jd-改" aria-label="Permalink to &quot;🎯 一、30 秒自我介绍（按这家 JD 改）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>7 年前端,主栈 React + TypeScript,做过商户管理 SaaS 平台和会员服务平台,</span></span>
<span class="line"><span>后台系统这块比较熟:antd 二次封装、列表页性能、表单联动、权限模型都踩过坑。</span></span>
<span class="line"><span>最近一年在做 AI 方向的探索(Agent 平台、前端 AI 应用集成),所以对 JD 里说的</span></span>
<span class="line"><span>&quot;AI 应用建设经验&quot;这块有实际落地,不是只听过概念。</span></span></code></pre></div><p><strong>三个关键词必须出现</strong>：后台管理 / 组件化与复用 / AI 应用落地。</p><hr><h2 id="📌-二、ant-design-必背-15-问" tabindex="-1">📌 二、Ant Design 必背 15 问 <a class="header-anchor" href="#📌-二、ant-design-必背-15-问" aria-label="Permalink to &quot;📌 二、Ant Design 必背 15 问&quot;">​</a></h2><blockquote><p>详细版：<a href="/前端/react/18-ant-design">Ant Design 实战</a></p></blockquote><table tabindex="0"><thead><tr><th>#</th><th>问题</th><th>一句话答案</th></tr></thead><tbody><tr><td>1</td><td>Form 为什么要 <code>useForm</code>？</td><td>拿到实例才能在组件外 <code>getFieldValue</code>/<code>setFieldsValue</code>/<code>validateFields</code>/<code>resetFields</code>；不传就是&quot;非受控 Form&quot;，外部只能靠 onFinish 拿值</td></tr><tr><td>2</td><td>Form 有哪几个关键 API？</td><td><code>getFieldValue</code>/<code>getFieldsValue</code>/<code>setFieldValue</code>/<code>setFieldsValue</code>/<code>resetFields</code>/<code>validateFields</code>/<code>getFieldError</code>/<code>isFieldsTouched</code></td></tr><tr><td>3</td><td>字段联动的标准写法？</td><td><code>Form.useWatch(&#39;a&#39;, form)</code> 订阅 + <code>useEffect</code> 联动；或 <code>Form.Item shouldUpdate</code> 精确控制重渲染范围</td></tr><tr><td>4</td><td>联动的坑？</td><td>隐藏字段的旧值会被一起提交 → 手动 <code>setFieldValue(f, undefined)</code> 或 <code>preserve={false}</code>；<code>useWatch([])</code> 订阅整个表单会全量 re-render</td></tr><tr><td>5</td><td>动态增删字段？</td><td><code>Form.List</code>（<code>fields</code>/<code>add</code>/<code>remove</code>/<code>move</code>），新增项必须给初值</td></tr><tr><td>6</td><td>Table 必写的属性？</td><td><code>rowKey</code>（不写会选中错乱）、<code>columns</code>（用 <code>useMemo</code> 稳定引用）、<code>scroll.x</code>（否则固定列不生效）</td></tr><tr><td>7</td><td>Table 排序筛选怎么做？</td><td><code>onChange(pagination, filters, sorter, extra)</code> 一次拿全，真实过滤排序交给后端；后端排序字段要白名单，防注入</td></tr><tr><td>8</td><td>1 万行表格怎么办？</td><td>ERP 首选<strong>后端分页</strong>（要跳页/导出/总数）；确需全量用 antd v5.9+ <code>virtual</code> + <code>scroll={{x,y}}</code></td></tr><tr><td>9</td><td>列多/列少分别怎么处理？</td><td>列多：<code>scroll.x</code> + 固定首尾列 + <code>ellipsis</code>；列少：用 <code>span</code> 合并栅格布局，别硬凑</td></tr><tr><td>10</td><td>主题定制怎么做？</td><td>Token 三层：全局 token / 组件 token / algorithm（<code>darkAlgorithm</code>）；<code>ConfigProvider theme={{ token, components }}</code></td></tr><tr><td>11</td><td>多租户换肤？</td><td>品牌色后端下发 → 运行时改 token + 注入 CSS 变量给非 antd 部分用</td></tr><tr><td>12</td><td><code>message</code> 主题不生效？</td><td>用了静态 <code>message.info()</code>，它脱离 ConfigProvider 上下文 → 根节点包 <code>&lt;App&gt;</code>，用 <code>App.useApp()</code></td></tr><tr><td>13</td><td>antd Form vs RHF+Zod？</td><td>antd 受控(store 订阅)、开箱即用、布局强；RHF 非受控、性能好、schema 可前后端共享。ERP 统一 antd，超大单表单用 RHF</td></tr><tr><td>14</td><td>二次封装怎么做？</td><td>只封装<strong>有业务语义</strong>的（StatusTag/PageTable/BizForm）；<code>pages → business → ui → antd</code> 依赖单向；透传 className/style/ref；自带 loading/empty/error 三件套</td></tr><tr><td>15</td><td>Element UI 也用过吗？</td><td>Vue 生态的对应物，思路一致（数据驱动 + 插槽扩展 + 主题变量覆盖）；React 岗主答 antd</td></tr></tbody></table><p><strong>三个一定要主动说的坑</strong>（面试官爱追问）：① 静态 message 丢主题；② 隐藏字段旧值被提交；③ Table 没写 rowKey / columns 没 memo。</p><hr><h2 id="📌-三、erp-crm-场景必背-12-问" tabindex="-1">📌 三、ERP / CRM 场景必背 12 问 <a class="header-anchor" href="#📌-三、erp-crm-场景必背-12-问" aria-label="Permalink to &quot;📌 三、ERP / CRM 场景必背 12 问&quot;">​</a></h2><blockquote><p>详细版：<a href="/面试/场景题/22-erp-crm场景">ERP / CRM 业务场景题</a></p></blockquote><table tabindex="0"><thead><tr><th>#</th><th>场景</th><th>关键答案</th></tr></thead><tbody><tr><td>1</td><td>列表组合筛选很慢</td><td>筛选全交后端 + 防抖 300ms + <code>AbortController</code> 取消竞态 + 条件写进 URL query + 后端分页</td></tr><tr><td>2</td><td>Excel 批量导入 5 万行</td><td>SheetJS 解析放 <strong>Web Worker</strong> → 表头映射 → 行级预校验 → 批量查重（不要一行一请求）→ 每批 500~1000 行提交 → <strong>失败行导出成错误报告</strong>让用户改后重传 → batchId 幂等</td></tr><tr><td>3</td><td>导出 10 万行崩了</td><td>前端生成必崩。走<strong>服务端异步导出</strong>：传筛选条件拿 taskId → 轮询/推送 → OSS 签名下载地址 → 下载中心。前端兜底：超 1 万行直接转后台任务</td></tr><tr><td>4</td><td>CSV 中文乱码</td><td>文件头加 UTF-8 BOM <code>\\uFEFF</code>；或干脆导 xlsx</td></tr><tr><td>5</td><td>三种客户字段不一样</td><td>Schema 驱动动态表单：字段元数据后端下发，<code>visible</code> + <code>useWatch</code> 做联动，<code>custom</code> 类型塞业务组件</td></tr><tr><td>6</td><td>审批流状态管理</td><td>前端用<strong>状态机</strong>（<code>TRANSITIONS</code> 映射表）而不是一堆 if；按钮按 <code>can(action, status)</code> 渲染；驳回必填意见；最终状态以后端返回为准；多人同时审批由后端校验状态机</td></tr><tr><td>7</td><td>两人同时改一条记录</td><td><strong>乐观锁 version</strong>：提交带 version，后端 <code>WHERE id=? AND version=?</code>，影响 0 行 → 409 → 提示刷新或字段级合并</td></tr><tr><td>8</td><td>不同角色看到不同数据</td><td>行级权限<strong>必须后端做</strong>（前端过滤是假过滤，接口已泄露）；列级脱敏后端做；前端只管 scope 切换 + 按钮级权限 + 数据范围提示</td></tr><tr><td>9</td><td>列表和详情数据不一致</td><td>TanStack Query 双缓存天然不一致 → invalidate / setQueryData 精准更新 / WebSocket 推送；标签页切回前台时 invalidate</td></tr><tr><td>10</td><td>切换租户要清什么</td><td>queryClient.clear() + store + localStorage + 字典/菜单/权限 + WebSocket 重连 + AbortController 取消在途请求；<strong>更稳：直接整页跳转</strong></td></tr><tr><td>11</td><td>动态表单（配置型）</td><td>Schema 下发 + 字段级组件拆分（各自 useWatch）+ 校验规则用 Zod 动态编译；性能坑是订阅整个表单</td></tr><tr><td>12</td><td>多人协作/离线编辑</td><td>CRDT（Yjs）/ 操作日志重放；乐观锁只解决&quot;最后写入者赢&quot;</td></tr></tbody></table><hr><h2 id="📌-四、监控与排障必背-6-问" tabindex="-1">📌 四、监控与排障必背 6 问 <a class="header-anchor" href="#📌-四、监控与排障必背-6-问" aria-label="Permalink to &quot;📌 四、监控与排障必背 6 问&quot;">​</a></h2><blockquote><p>详细版：<a href="/前端/monitoring/1-异常监控与错误上报">异常监控与错误上报</a> · <a href="/前端/monitoring/2-线上问题定位与降级">线上问题定位与降级</a></p></blockquote><table tabindex="0"><thead><tr><th>#</th><th>问题</th><th>关键答案</th></tr></thead><tbody><tr><td>1</td><td>线上错误怎么发现？</td><td><code>window.onerror</code>（同步 + 资源错误，捕获阶段）+ <code>unhandledrejection</code>（异步）+ React ErrorBoundary（渲染）→ 上报 Sentry/自建 → 按分级告警</td></tr><tr><td>2</td><td>上报要带什么字段？</td><td>message/stack/componentStack + URL/路由 + userId/租户 + release 版本 + 设备浏览器 + <strong>最近操作路径 breadcrumb</strong>。没有上下文的上报等于没上报</td></tr><tr><td>3</td><td>生产为什么配 SourceMap？</td><td>压缩后堆栈不可读。构建生成 .map 上传监控平台 → 线上错误能还原到源码行。<strong>上传完必须从静态服务器删掉</strong>，否则源码泄露</td></tr><tr><td>4</td><td>ErrorBoundary 能捕获哪些？</td><td>只能捕获 React 渲染树内、渲染/生命周期阶段的错误；事件回调和异步回调不会冒泡，要自己 try/catch</td></tr><tr><td>5</td><td>用户说&quot;页面打不开&quot;怎么查？</td><td>① 确认影响面 ② 看监控（错误率/接口成功率/资源 404/白屏率）③ 按 release 聚合 ④ 用操作轨迹复现 ⑤ <strong>先止损</strong>（回滚/关开关/降级）再定位 ⑥ 复盘出带 owner 的改进项</td></tr><tr><td>6</td><td>前端怎么降级？</td><td>功能开关（按租户/百分比灰度）+ 数据降级（缓存兜底、4xx 不重试）+ 渲染降级（ErrorBoundary 局部兜底不全页白屏）+ 极端情况按顺序关功能。前提：<strong>每条降级路径都有测试</strong></td></tr></tbody></table><hr><h2 id="📌-五、typescript-必背-6-问" tabindex="-1">📌 五、TypeScript 必背 6 问 <a class="header-anchor" href="#📌-五、typescript-必背-6-问" aria-label="Permalink to &quot;📌 五、TypeScript 必背 6 问&quot;">​</a></h2><blockquote><p>详细版：<a href="/面试/TypeScript/15-进阶面试题">进阶面试题 Q11-Q25</a></p></blockquote><table tabindex="0"><thead><tr><th>#</th><th>问题</th><th>关键答案</th></tr></thead><tbody><tr><td>1</td><td>泛型组件怎么写？</td><td><code>function List&lt;T&gt;(props)</code>；<code>.tsx</code> 里箭头函数要写 <code>&lt;T,&gt;</code> 否则被当 JSX</td></tr><tr><td>2</td><td>泛型 Hook 怎么写？</td><td>泛型放调用点推导：<code>queryFn: () =&gt; request&lt;User&gt;(url)</code>，调用方不用再断言</td></tr><tr><td>3</td><td><code>satisfies</code> vs <code>as const</code>？</td><td><code>satisfies</code> 校验结构<strong>同时保留字面量类型</strong>；<code>as const</code> 保留字面量但<strong>不校验</strong>。做路由表/权限点常量用 satisfies</td></tr><tr><td>4</td><td>穷尽检查怎么做？</td><td><code>switch</code> + <code>default: assertNever(x)</code>，<code>x: never</code>；新增状态时编译期报错</td></tr><tr><td>5</td><td><code>unknown</code> vs <code>any</code>？</td><td>外部数据一律 <code>unknown</code> 再收窄；<code>any</code> 会传染整个表达式</td></tr><tr><td>6</td><td>什么时候用类型断言？</td><td>只在你比编译器更清楚类型时；更好的做法是类型守卫 <code>x is T</code> 或 Zod 校验</td></tr></tbody></table><hr><h2 id="📌-六、三个-我做过-的故事-star-压缩到-60-秒" tabindex="-1">📌 六、三个&quot;我做过&quot;的故事（STAR 压缩到 60 秒） <a class="header-anchor" href="#📌-六、三个-我做过-的故事-star-压缩到-60-秒" aria-label="Permalink to &quot;📌 六、三个&quot;我做过&quot;的故事（STAR 压缩到 60 秒）&quot;">​</a></h2><h3 id="故事-1-后台列表页性能治理-对应-性能优化-条款" tabindex="-1">故事 1：后台列表页性能治理（对应&quot;性能优化&quot;条款） <a class="header-anchor" href="#故事-1-后台列表页性能治理-对应-性能优化-条款" aria-label="Permalink to &quot;故事 1：后台列表页性能治理（对应&quot;性能优化&quot;条款）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>S：商户管理 SaaS 的客户列表，1 万+ 数据，翻页卡顿，运营抱怨</span></span>
<span class="line"><span>T：把首屏从 3s 降到 1s 内</span></span>
<span class="line"><span>A：① 全量拉取改后端分页 + 组合筛选下推；② Table 加 rowKey + columns useMemo</span></span>
<span class="line"><span>   + 行内编辑抽成 memo 子组件；③ 大数据量视图用虚拟滚动</span></span>
<span class="line"><span>   ④ 接入 Web Vitals 上报 LCP/INP，按版本对比</span></span>
<span class="line"><span>R：首屏 3s → 0.9s，长任务从 6 个降到 1 个</span></span></code></pre></div><p><strong>可追加</strong>：虚拟滚动不适合需要跳页/导出的后台场景，所以最终选了分页 —— 讲取舍，比讲技术更加分。</p><h3 id="故事-2-组件沉淀与复用-对应-组件化设计与实现-条款" tabindex="-1">故事 2：组件沉淀与复用（对应&quot;组件化设计与实现&quot;条款） <a class="header-anchor" href="#故事-2-组件沉淀与复用-对应-组件化设计与实现-条款" aria-label="Permalink to &quot;故事 2：组件沉淀与复用（对应&quot;组件化设计与实现&quot;条款）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>S：多个页面重复写弹窗 + 表单 + 状态标签，改一次要改 5 个文件</span></span>
<span class="line"><span>T：抽成可复用业务组件</span></span>
<span class="line"><span>A：① StatusTag 把&quot;状态 → 颜色/文案&quot;映射收口，用 as const + keyof 保证类型</span></span>
<span class="line"><span>   ② PageTable 统一 loading/分页/空态/错误态，暴露 toolbar 插槽</span></span>
<span class="line"><span>   ③ 目录分层 pages → business → ui → antd，依赖单向</span></span>
<span class="line"><span>   ④ 配套 Storybook 文档 + 单元测试</span></span>
<span class="line"><span>R：同类需求交付从 3 天降到 1 天，复用率从 0 到 60%+</span></span></code></pre></div><h3 id="故事-3-ai-能力落地-对应-ai-应用建设经验-加分项" tabindex="-1">故事 3：AI 能力落地（对应&quot;AI 应用建设经验&quot;加分项） <a class="header-anchor" href="#故事-3-ai-能力落地-对应-ai-应用建设经验-加分项" aria-label="Permalink to &quot;故事 3：AI 能力落地（对应&quot;AI 应用建设经验&quot;加分项）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>S：运营录入客户信息慢，字段多、格式乱</span></span>
<span class="line"><span>T：做个 AI 辅助录入提效</span></span>
<span class="line"><span>A：① 失焦触发，后端调 LLM + 工商信息 API 回填</span></span>
<span class="line"><span>   ② 所有 AI 结果标&quot;AI 生成&quot;标识，**必须人工确认才落库**（不直接写业务数据）</span></span>
<span class="line"><span>   ③ 流式输出用 SSE，主线程可中断</span></span>
<span class="line"><span>   ④ 脱敏：PII 不出网</span></span>
<span class="line"><span>R：录入耗时下降，人工采纳率 XX%</span></span></code></pre></div><blockquote><p>⚠️ 讲 AI 时<strong>一定要带上&quot;人工确认 + 脱敏 + 兜底&quot;</strong>，不然面试官会担心合规风险。</p></blockquote><hr><h2 id="📌-七、ai-差异化打法-30-秒版" tabindex="-1">📌 七、AI 差异化打法（30 秒版） <a class="header-anchor" href="#📌-七、ai-差异化打法-30-秒版" aria-label="Permalink to &quot;📌 七、AI 差异化打法（30 秒版）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>JD 写&quot;有 AI 应用建设经验的优先考虑&quot;,这是你相对 3 年经验候选人的最大差异点:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 不说&quot;我用过 Copilot&quot;,说&quot;我做过 AI 应用的前端集成&quot;:</span></span>
<span class="line"><span>  流式输出(SSE/ReadableStream)、Function Calling、Prompt 模板管理、</span></span>
<span class="line"><span>  RAG 检索结果可视化、LLM 应用的权限与降级设计</span></span>
<span class="line"><span>- 强调你是&quot;前端 + AI 应用&quot;双栈,不是只会调 API</span></span>
<span class="line"><span>- 一句话收尾:&quot;AI 在后台系统的价值不是炫技,是把重复录入和查询自动化,</span></span>
<span class="line"><span>  同时保留人工确认和审计,不然业务不敢用。&quot;</span></span></code></pre></div><hr><h2 id="📌-八、反问面试官-挑-2-3-个问-别问薪资" tabindex="-1">📌 八、反问面试官（挑 2~3 个问，别问薪资） <a class="header-anchor" href="#📌-八、反问面试官-挑-2-3-个问-别问薪资" aria-label="Permalink to &quot;📌 八、反问面试官（挑 2~3 个问，别问薪资）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 这个 ERP/CRM 产品主要面向哪些客户？核心业务模块大概是哪些？</span></span>
<span class="line"><span>   （显得你在认真理解业务，而不是只想写代码）</span></span>
<span class="line"><span>2. 前端团队现在的技术栈和组件库是 antd 吗？有没有自己的设计系统或组件库？</span></span>
<span class="line"><span>3. 前端在需求评审里的话语权怎么样？技术方案通常由谁来定？</span></span>
<span class="line"><span>4. 团队现在的痛点更偏业务迭代速度，还是性能/稳定性？</span></span>
<span class="line"><span>5. 团队规模多大？前端几个人？代码评审和测试流程是怎样的？</span></span>
<span class="line"><span>6. JD 提到 AI 应用建设，目前是在规划阶段还是已有落地场景？</span></span></code></pre></div><blockquote><p>第 6 个一定要问 —— 顺势把 AI 话题拉回来深入聊。</p></blockquote><hr><h2 id="📌-九、红线-这些话别说" tabindex="-1">📌 九、红线：这些话别说 <a class="header-anchor" href="#📌-九、红线-这些话别说" aria-label="Permalink to &quot;📌 九、红线：这些话别说&quot;">​</a></h2><table tabindex="0"><thead><tr><th>❌ 别说</th><th>✅ 改成</th></tr></thead><tbody><tr><td>&quot;antd 我用过，会用就行&quot;</td><td>&quot;antd 的 Table 受控模型和 Form 的字段联动我熟，我们还做过二次封装&quot;</td></tr><tr><td>&quot;性能优化就是加个 memo&quot;</td><td>&quot;性能我按 渲染 / 网络 / 资源 三层拆，列表页做过专门治理&quot;</td></tr><tr><td>&quot;AI 我用过 ChatGPT 写代码&quot;</td><td>&quot;我做过 AI 应用的前端集成：流式、工具调用、RAG 可视化&quot;</td></tr><tr><td>&quot;权限就是后端返回的菜单&quot;</td><td>&quot;菜单/路由/按钮/接口四层权限用同一份权限点常量生成&quot;</td></tr><tr><td>&quot;导出就是 xlsx 库生成&quot;</td><td>&quot;1 万行以内前端生成可以，超过就转服务端异步导出 + 下载中心&quot;</td></tr><tr><td>&quot;报错就 console.log 看看&quot;</td><td>&quot;线上有全局捕获 + Sentry 上报 + 错误分级告警&quot;</td></tr><tr><td>不会就硬编</td><td>&quot;这块我没深入做过，但我的思路是……我会先……&quot;</td></tr></tbody></table><hr><h2 id="📌-十、临场应急话术" tabindex="-1">📌 十、临场应急话术 <a class="header-anchor" href="#📌-十、临场应急话术" aria-label="Permalink to &quot;📌 十、临场应急话术&quot;">​</a></h2><p><strong>不会的问题</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;这个我没在实际项目里用过。不过按我的理解是……（说出你知道的相邻原理）。</span></span>
<span class="line"><span>如果让我做，我会先……再……&quot;</span></span></code></pre></div><p>—— 展示的是<strong>思考方式</strong>，比硬编安全得多。</p><p><strong>被质疑深度</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;你说得对，我刚才那个说法不够准确。准确地说应该是……&quot;</span></span></code></pre></div><p>—— 承认 + 立刻修正，比坚持错答案加分。</p><p><strong>问到你博客里的内容</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;这块我在自己的技术笔记里整理过，我的思路是……&quot;</span></span></code></pre></div><p>—— 展示你有沉淀习惯，这是加分项。</p><p><strong>面试官问&quot;还有什么想问的&quot;</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;我看到贵司是 ERP/CRM 方向，前端在业务系统里最难的应该是表格和表单的性能与一致性，</span></span>
<span class="line"><span>我挺想了解你们现在是怎么解决的。&quot;</span></span></code></pre></div><hr><h2 id="🔗-相关文档" tabindex="-1">🔗 相关文档 <a class="header-anchor" href="#🔗-相关文档" aria-label="Permalink to &quot;🔗 相关文档&quot;">​</a></h2><ul><li><a href="/前端/react/18-ant-design">Ant Design 实战</a></li><li><a href="/面试/场景题/22-erp-crm场景">ERP / CRM 业务场景题</a></li><li><a href="/前端/monitoring/1-异常监控与错误上报">异常监控与错误上报</a></li><li><a href="/前端/monitoring/2-线上问题定位与降级">线上问题定位与降级</a></li><li><a href="/面试/TypeScript/15-进阶面试题">TypeScript 进阶面试题</a></li><li><a href="/前端/design-patterns/2-React组件设计模式">React 组件设计模式</a></li><li><a href="/前端/ai-integration/">前端 + AI 集成专题</a></li><li><a href="/面试/2-复习清单">复习清单</a></li><li><a href="/面试/3-自我介绍">自我介绍</a></li></ul>`,59)])])}const g=a(n,[["render",o]]);export{u as __pageData,g as default};
